      public_deps += [ "src/profiling/smaps:smaps" ]
    }
    sources = [ "include/perfetto/tracing.h" ]
    assert_no_deps = [ "gn:protobuf_lite" ]

    # Abseil is used in Perfetto via gRPC/libprotobuf and RE2.  When RE2 is
    # not enabled, abseil should not be pulled in transitively.
    if (!enable_perfetto_re2 &&
